-- 箱庭 -- 电路系统 -- 电器设备 -- 滑动闸门;
-- 带电第一帧会触发闸门从 srcPos 运动到 dstPos:

-- 最简模式: 只要发现本电器通电, 滑动门就进入 移动状态, 哪怕下一帧立马断电也不受影响;
-- todo: 另一种可能的模式: 必须给本电器持续输入电力, 门才能维持运动, 只要中途断开电路, 门就会向 srcPos 恢复运动
    


---@class SlidingDoor
---@field gateTF              UnityEngine.Transform
---@field srcPosTF            UnityEngine.Transform
---@field dstPosTF            UnityEngine.Transform
---@field params              Engine.Modules.LuaParameters 
local SlidingDoor = Class('SlidingDoor')



-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


local QuestUtils = import('Game.DreamSpace.Quest.QuestUtils')
---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

---@type DreamSpaceSounds
local DreamSpaceSounds = import('Game.DreamSpace.Tools.DreamSpaceSounds'):GetInstance()

local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')
---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3
local Quaternion = CS.UnityEngine.Quaternion
local Color = CS.UnityEngine.Color
local Time = CS.UnityEngine.Time
local Text = CS.UnityEngine.UI.Text
local Image = CS.UnityEngine.UI.Image
local Animation = CS.UnityEngine.Animation
local Animator = CS.UnityEngine.Animator
local Mathf = CS.UnityEngine.Mathf

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters

local ElectricalTrigger = CS.ElectricalSystem.ElectricalTrigger
local Interrupter = CS.ElectricalSystem.ElectricalSwitch.Interrupter
local OnOff = CS.Game.OnOff

local ElectricalApplianceBase = CS.ElectricalSystem.ElectricalApplianceBase



-- ========================================================


local State = 
{
    Src = 0,        -- 位于起点
    OnMoving = 1,   -- 正在移动
    Dst = 2         -- 到达终点
}


-- ========================================================

function SlidingDoor:__init()
    self.controller = nil

    self.currentVelocity = Vector3.zero
end


function SlidingDoor:__delete()
end


function SlidingDoor:Start()

    assert( self.gateTF and self.srcPosTF and self.dstPosTF and self.params )

    self:GetInspectorParams()

    self.state = State.Src

    self.gateTF.position = self.srcPosTF.position

    self:BindPowerOnEvent()   
end


function SlidingDoor:GetInspectorParams()
    self.duration = LuaParametersReader.Read( self.params, "duration", LuaParametersReader.Type.Float )
    self.isCenterElevator = LuaParametersReader.Read( self.params, "isCenterElevator", LuaParametersReader.Type.Bool )
    assert( self.duration and type(self.isCenterElevator) == "boolean")
end


function SlidingDoor:BindPowerOnEvent()
    self.eBase = KTool.GetComponent(self.controller.gameObject, typeof(ElectricalApplianceBase))
    self.eBase:OnHandleElectrifiedState( '+', function( brain_ ) 
        if ( self.state == State.Src ) then
            self.state = State.OnMoving
            DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
            self.co_1 = cs_coroutine.start( self.MoveEquipment, self ) 
            self:PlayMovementSound()
        end
    end ) 
end


function SlidingDoor:PlayMovementSound()
    DreamSpaceSounds.Stop( DreamSpaceSounds.sfx.electricCurrent )
    if self.isCenterElevator then
        DreamSpaceSounds.Play( DreamSpaceSounds.sfx.heavyElevatorMove )
    else
        DreamSpaceSounds.Play( DreamSpaceSounds.sfx.elevatorMove )
    end
end


function SlidingDoor:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- ret IEnumerator
function SlidingDoor:MoveEquipment()
    self.startTime = Time.time
    self.startY = self.srcPosTF.position.y
    self.endY = self.dstPosTF.position.y

    while Mathf.Abs(self.gateTF.position.y - self.endY) > Mathf.Epsilon do
        local t = (Time.time - self.startTime) / self.duration
        local newY = Mathf.SmoothStep(self.startY, self.endY, t)
        self.gateTF.position = Vector3(self.gateTF.position.x, newY, self.gateTF.position.z)
        coroutine.yield(Yielders.EndOfFrame)
    end

    if self.isCenterElevator then
        DreamSpaceSounds.Play( DreamSpaceSounds.sfx.heavyElevatorHit )
    else
        DreamSpaceSounds.Play( DreamSpaceSounds.sfx.elevatorHit )
    end

    self.state = State.Dst;
end 


return SlidingDoor

